    type UpdateEvent = { event: string; data?: { chunkLength?: number; contentLength?: number } };
    // downloadAndInstall 挂起以维持 downloading 形态；事件回调经 channel 捕获后按拍派发
    const channel: { emit: ((event: UpdateEvent) => void) | null } = { emit: null };
